import AppKit
import Foundation

// MARK: - Embedded Spider-Man Mask Eye Assets (Lossless PNG Base64)
public enum SpiderEyesAssets {
    public static let leftImage: NSImage? = {
        let b64 = ""
        guard let data = Data(base64Encoded: b64) else { return nil }
        return NSImage(data: data)
    }()
    
    public static let rightImage: NSImage? = {
        let b64 = ""
        guard let data = Data(base64Encoded: b64) else { return nil }
        return NSImage(data: data)
    }()
}

